from fractions import Fraction as Q
from math import factorial,comb
def moment(n,T):
 return Q(0) if n%4 else Q(factorial(n),factorial(n//4))*(-T)**(n//4)
def falling(n,r):return Q(0) if n<r else Q(factorial(n),factorial(n-r))
def integrated_mixed(k,l,T):
 if l<0:return Q(0)
 ans=Q(0)
 for a in range(l+1):
  if (k+a)%4 or (l-a)%4:continue
  A=(k+a)//4;B=(l-a)//4
  ans+=comb(l,a)*Q(factorial(k+a),factorial(A))*Q(factorial(l-a),factorial(B))*(-T)**(A+B)*Q(factorial(A)*factorial(B),factorial(A+B+1))
 return ans
checks=0;examples=[]
for T in [Q(1),Q(1,2),Q(2),Q(5,7)]:
 for g in range(18):
  first=3*(-4*T)*falling(g,3)*integrated_mixed(2,g-3,T)
  second=3*(-12*T)*falling(g,2)*integrated_mixed(1,g-2,T)
  third=Q(0) if g==0 else -24*T*g*moment(g-1,T)
  assert first+second+third==moment(g+3,T)
  if g==1:assert (first,second,third)==(0,0,-24*T)
  if g==5:assert (first,second,third)==(8640*T*T,8640*T*T,2880*T*T)
  if T==1 and g in [1,5,9]:examples.append(dict(probe_degree=g,three_weighted_channels=[str(first),str(second),str(third)],actual_terminal_moment=str(moment(g+3,T))))
  checks+=1
print(dict(exact_three_channel_tests=checks,passed=True,examples=examples,scope='Independent signed moment and exact time integration checks; completed-dual reconstruction is proved separately in Lean'))
